from taf.sw.dcap.rd.schemas.base import SchemaField, SchemaObject


class BTSInfoCMV1(SchemaObject):
    bts_id = SchemaField(name="id")
    alias = SchemaField(name="alias")
    name = SchemaField(name="name")
    mr_bts_id = SchemaField(name="mr_bts_id")
    latitude = SchemaField(name="latitude")
    longitude = SchemaField(name="longitude")
    altitude = SchemaField(name="altitude")
    sw_version = SchemaField(name="sw_version")
    major_sw_version = SchemaField(name="major_sw_version")
    type = SchemaField(name="type")
    host = SchemaField(name="host")
    port = SchemaField(name="port")
    password = SchemaField(name="password")
    username = SchemaField(name="username")
    nr_cells = SchemaField(name="nr_cells")
    lte_cells = SchemaField(name="lte_cells")
    internal_trace_enabled = SchemaField(name="internal_trace_enabled")
    user_provided_credentials_required = SchemaField(name="user_provided_credentials_required")

    def __init__(self, bts_id, alias, name, mr_bts_id, latitude, longitude, altitude,
                 sw_version, major_sw_version, type, host, port, username, password,
                 nr_cells, lte_cells, internal_trace_enabled, user_provided_credentials_required):
        self.bts_id = bts_id
        self.alias = alias
        self.name = name
        self.mr_bts_id = mr_bts_id
        self.latitude = latitude
        self.longitude = longitude
        self.altitude = altitude
        self.sw_version = sw_version
        self.major_sw_version = major_sw_version
        self.type = type
        self.host = host
        self.port = port
        self.password = password
        self.username = username
        self.nr_cells = nr_cells
        self.lte_cells = lte_cells
        self.internal_trace_enabled = internal_trace_enabled
        self.user_provided_credentials_required = user_provided_credentials_required

        super(BTSInfoCMV1, self).__init__()
